set -eu
cat > inspect_deseq.R <<'RSCRIPT'
suppressPackageStartupMessages({
  library(DESeq2)
})
args <- commandArgs(trailingOnly=TRUE)
items <- list(res_1vs97=args[1], res_1vs98=args[2])
target <- 'PA14_35160'
for (nm in names(items)) {
  obj <- readRDS(items[[nm]])
  cat('dataset\t', nm, '\n', sep='')
  cat('class\t', paste(class(obj), collapse=','), '\n', sep='')
  md <- S4Vectors::metadata(obj)
  if (length(md) == 0) {
    cat('metadata\t<empty>\n')
  } else {
    cat('metadata_names\t', paste(names(md), collapse=','), '\n', sep='')
    if ('contrast' %in% names(md)) cat('metadata_contrast\t', paste(as.character(md$contrast), collapse='|'), '\n', sep='')
    if ('alpha' %in% names(md)) cat('metadata_alpha\t', as.character(md$alpha), '\n', sep='')
    if ('lfcThreshold' %in% names(md)) cat('metadata_lfcThreshold\t', as.character(md$lfcThreshold), '\n', sep='')
    if ('test' %in% names(md)) cat('metadata_test\t', as.character(md$test), '\n', sep='')
    if ('filterThreshold' %in% names(md)) cat('metadata_filterThreshold\t', paste(as.character(md$filterThreshold), collapse='|'), '\n', sep='')
  }
  df <- as.data.frame(obj)
  if (!(target %in% rownames(df))) stop(paste('target not found:', target, 'in', nm))
  row <- df[target, , drop=FALSE]
  cat('target_header\trowname\t', paste(colnames(row), collapse='\t'), '\n', sep='')
  cat('target_row\t', target, '\t', paste(vapply(row[1,], function(x) as.character(x), character(1)), collapse='\t'), '\n', sep='')
  cat('---\n')
}
